// Helper to look up course by active slug or legacy alias
export const getCourseBySlug = (slug) => {
  if (!slug) return null;
  const clean = slug.toLowerCase().trim();
  return COURSES.find(
    (c) => c.slug === clean || (c.legacySlugs && c.legacySlugs.includes(clean))
  );
};
